CREATE EXTENSION IF NOT EXISTS citext;
CREATE TABLE IF NOT EXISTS tenants (id text PRIMARY KEY, label text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sites (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), label text NOT NULL, repo text NOT NULL, branch text NOT NULL DEFAULT 'main', provider text NOT NULL, api_root text NOT NULL UNIQUE, allowed_origins jsonb NOT NULL DEFAULT '[]', credential_ref text, enabled boolean NOT NULL DEFAULT true, settings jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email citext NOT NULL UNIQUE, name text NOT NULL, password_hash text, google_sub text UNIQUE, totp_secret text, totp_enabled boolean NOT NULL DEFAULT false, disabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), last_login_at timestamptz);
CREATE TABLE IF NOT EXISTS memberships (user_id uuid NOT NULL REFERENCES users(id), site_id text NOT NULL REFERENCES sites(id), role text NOT NULL CHECK (role IN ('admin','editor','author','viewer')), invited_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id, site_id));
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text NOT NULL UNIQUE, user_id uuid NOT NULL REFERENCES users(id), site_id text NOT NULL REFERENCES sites(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, user_agent text, ip_hash text);
CREATE TABLE IF NOT EXISTS git_credentials (id text PRIMARY KEY, provider text NOT NULL, installation_ref text, encrypted_secret text, key_id text NOT NULL DEFAULT 'v1', cached_token text, token_expires_at timestamptz);
CREATE TABLE IF NOT EXISTS audit (id bigserial PRIMARY KEY, site_id text NOT NULL REFERENCES sites(id), user_id uuid REFERENCES users(id), method text NOT NULL, path text NOT NULL, status integer NOT NULL, byte_size integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_attempts (key text PRIMARY KEY, count integer NOT NULL DEFAULT 0, first_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invites (email citext NOT NULL, site_id text NOT NULL REFERENCES sites(id), role text NOT NULL, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_by uuid NOT NULL REFERENCES users(id), accepted_at timestamptz, PRIMARY KEY(email, site_id));
CREATE INDEX IF NOT EXISTS sessions_user_site_idx ON sessions(user_id, site_id);
CREATE INDEX IF NOT EXISTS audit_site_created_idx ON audit(site_id, created_at DESC);
